        return True

    if dr > 0 and dc > 0:  # / direction (down-right)
        rr = center[0] + 1
        cc_inner, center_cc = center[1] + 1, center[1]
        while rr <= r and cc_inner <= c:
            if grid[rr][cc_inner] == 2:
                return False
            rr += 1
            cc_inner += 1
        return True

    if dr < 0 and dc < 0:  # / direction (up-left)
        rr = center[0] - 1
        cc_inner, center_cc = center[1] - 1, center[1]
        while rr >= r and cc_inner >= c:
            if grid[rr][cc_inner] == 2:
                return False
            rr -= 1
            cc_inner -= 1
        return True

