def box_blocked(r, c, grid, center):
    """Check if rectangle from center to (r,c) is blocked by any 2"""
    min_r, max_r = min(r, center[0]), max(r, center[0])
    min_c, max_c = min(c, center[1]), max(c, center[1])

    # Check if rectangle contains any 2
    for rr in range(min_r, max_r + 1):
        for cc in range(min_c, max_c + 1):
            if grid[rr][cc] == 2:
                return True
    return False

